# Generated by plotwork generate from the source infra-dev (terraform: infra/terraform/**/*.tf, infra/terraform/**/*.tfvars).
# The next run writes over this file. Put changes in docs/infra-dev.overrides.json, or run plotwork generate --capture
# after an edit to keep it there, then run plotwork generate.
flow "Parcelpoint on Azure, development" direction=down provider=azure desc="29 resources on Azure, framed by the module that declares them and nested in the groups, networks, and subnets that hold them, imported from Terraform. An arrow means one resource refers to another, and its label says how: a role, a private link, logs, or a secret."

group azure_account "Azure subscription" type=account {

  group main "rg-parcel-dev" type=resource-group sub="westeurope" {

    group monitoring "Monitoring" type=observability icon=lucide:package sub="Module modules/monitoring" {
      node this_3 service "log-parcel-dev" sub="Log Analytics workspace PerGB2018" icon=azure:log-analytics-workspaces
      node this_4 service "appi-parcel-dev" sub="Application Insights web" icon=azure:application-insights
    }

    group compute "Compute" type=resource-group icon=lucide:package sub="Module modules/compute" {
      node apps identity "id-parcel-dev-apps" sub="Managed identity" icon=azure:managed-identities

      group this_2 "asp-parcel-dev" type=service-plan {
        node api service "app-parcel-dev-api" sub="App Service" icon=azure:app-service
        node worker function "func-parcel-dev-events" sub="Function app" icon=azure:functions
        node this_service_plan service "Service plan" sub="B1 Linux" icon=azure:app-service-plans
      }
    }

    group network "Network" type=network icon=lucide:package sub="Module modules/network" {
      node postgres gateway "privatelink.postgres.database.azure.com" sub="Private DNS zone" icon=azure:dns-zones

      group this "vnet-parcel-dev" type=network {
        node this_network service "Virtual network" icon=azure:virtual-network

        group app "snet-parcel-dev-app" type=subnet {
          node app_2 secret "nsg-parcel-dev-app" sub="Network security group" icon=azure:network-security-groups
          node app_subnet service "Subnet" icon=azure:subnet
        }

        group data "snet-parcel-dev-data" type=subnet {
          node data_subnet service "Subnet" icon=azure:subnet
        }

        group endpoints "snet-parcel-dev-endpoints" type=subnet {
          node endpoints_subnet service "Subnet" icon=azure:subnet
        }
      }
    }

    group data_2 "Data" type=resource-group icon=lucide:package sub="Module modules/data" {
      node labels_3 gateway "pe-parcel-dev-labels" sub="Private endpoint" icon=azure:private-endpoints

      group this_group "psql-parcel-dev" type=data-tier icon=azure:database-for-postgresql {
        node postgres_2 service "Postgres password" icon=lucide:key-round
        node this_5 database "PostgreSQL flexible server" sub="B_Standard_B1ms" icon=azure:database-for-postgresql
        node tracking database "tracking" sub="Database" icon=azure:database-for-postgresql
      }

      group labels_group "stparceldevlabels" type=storage-account icon=azure:storage-accounts {
        node labels storage "Storage account" sub="Standard" icon=azure:storage-accounts
        node labels_2 storage "labels" sub="Blob container" icon=azure:storage-container
      }

      group this_group_2 "sb-parcel-dev" type=messaging icon=azure:service-bus {
        node this_6 queue "Service Bus namespace" sub="Standard" icon=azure:service-bus
        node carrier_events queue "carrier-events" sub="Service Bus queue" icon=azure:service-bus
      }

      group this_group_3 "kv-parcel-dev" type=security icon=azure:key-vault {
        node this_7 secret "Key Vault" sub="standard" icon=azure:key-vault
        node postgres_password secret "postgres-password" sub="Secret" icon=azure:keys
      }
    }
  }
}

this_4 -> this_3 : "logs" icon=lucide:activity
app_2 -> this_3 : "diagnostics"
postgres -> this_network : "DNS link"
this_5 -> data_subnet : "subnet"
this_5 -> postgres : "DNS"
this_5 -> postgres_2 : "password" icon=lucide:key-round role=identity
labels_3 -> labels : "private link" icon=lucide:lock role=private
labels_3 -> endpoints_subnet : "subnet"
postgres_password -> postgres_2 : "holds"
apps -> labels : "Storage Blob Data Contributor" icon=lucide:key-round role=identity
apps -> this_6 : "Azure Service Bus Data Receiver" icon=lucide:key-round role=identity
apps -> this_7 : "Key Vault Secrets User" icon=lucide:key-round role=identity
this_service_plan -> app_subnet : "VNet integration (2)" icon=lucide:lock role=private
this_service_plan -> this_4 : "telemetry (2)" icon=lucide:activity
this_service_plan -> this_5 : "data (2)" icon=lucide:database role=data
api -> postgres_password : "secret" icon=lucide:key-round role=identity
this_service_plan -> labels : "storage (2)" icon=lucide:database role=data
this_service_plan -> apps : "identity (2)" icon=lucide:key-round role=identity
worker -> carrier_events : "messages" icon=lucide:send role=async
tracking -> this_5 : "part of"
labels_2 -> labels : "part of"
